   495  /**
   496   * idn2_lookup_ul:
   497   * @src: input zero-terminated locale encoded string.
   498   * @lookupname: newly allocated output variable with name to lookup in DNS.
   499   * @flags: optional #idn2_flags to modify behaviour.
   500   *
   501   * Perform IDNA2008 lookup string conversion on domain name @src, as
   502   * described in section 5 of RFC 5891.  Note that the input is assumed
   503   * to be encoded in the locale's default coding system, and will be
   504   * transcoded to UTF-8 and NFC normalized by this function.
   505   *
   506   * Pass %IDN2_ALABEL_ROUNDTRIP in @flags to convert any input A-labels
   507   * to U-labels and perform additional testing.  Pass
   508   * %IDN2_TRANSITIONAL to enable Unicode TR46 transitional processing,
   509   * and %IDN2_NONTRANSITIONAL to enable Unicode TR46 non-transitional
   510   * processing.  Multiple flags may be specified by binary or:ing them
   511   * together, for example %IDN2_ALABEL_ROUNDTRIP |
   512   * %IDN2_NONTRANSITIONAL.  The %IDN2_NFC_INPUT in @flags is always
   513   * enabled in this function.
   514   *
   515   * After version 0.11: @lookupname may be NULL to test lookup of @src
   516   * without allocating memory.
   517   *
   518   * Returns: On successful conversion %IDN2_OK is returned, if
   519   *   conversion from locale to UTF-8 fails then %IDN2_ICONV_FAIL is
   520   *   returned, if the output domain or any label would have been too
   521   *   long %IDN2_TOO_BIG_DOMAIN or %IDN2_TOO_BIG_LABEL is returned, or
   522   *   another error code is returned.
   523   *
   524   * Since: 0.1
   525   **/
   526  int
   527  idn2_lookup_ul (const char * src, char ** lookupname, int flags)
   528  {
   529    uint8_t *utf8src = NULL;
   530    int rc;
   531
   532    if (src)
   533      {
   534        const char *encoding = locale_charset ();
   535
   536        utf8src = u8_strconv_from_encoding (src, encoding, iconveh_error);
   537
   538        if (!utf8src)
   539          {
   540            if (errno == ENOMEM)
   541              return IDN2_MALLOC;
   542            return IDN2_ICONV_FAIL;
   543          }
   544      }
   545
   546    rc = idn2_lookup_u8 (utf8src, (uint8_t **) lookupname,
   547                         flags | IDN2_NFC_INPUT);
   548
   549    free (utf8src);
   550
   551    return rc;
   552  }
