   619  /**
   620   * idn2_to_ascii_4i:
   621   * @input: zero terminated input Unicode (UCS-4) string.
   622   * @inlen: number of elements in @input.
   623   * @output: pointer to newly allocated zero-terminated output string.
   624   * @flags: optional #idn2_flags to modify behaviour.
   625   *
   626   * The ToASCII operation takes a sequence of Unicode code points that make
   627   * up one domain label and transforms it into a sequence of code points in
   628   * the ASCII range (0..7F). If ToASCII succeeds, the original sequence and
   629   * the resulting sequence are equivalent labels.
   630   *
   631   * It is important to note that the ToASCII operation can fail.
   632   * ToASCII fails if any step of it fails. If any step of the
   633   * ToASCII operation fails on any label in a domain name, that domain
   634   * name MUST NOT be used as an internationalized domain name.
   635   * The method for dealing with this failure is application-specific.
   636   *
   637   * The inputs to ToASCII are a sequence of code points.
   638   *
   639   * ToASCII never alters a sequence of code points that are all in the ASCII
   640   * range to begin with (although it could fail). Applying the ToASCII operation multiple
   641   * effect as applying it just once.
   642   *
   643   * The default behavior of this function (when flags are zero) is to apply
   644   * the IDNA2008 rules without the TR46 amendments. As the TR46
   645   * non-transitional processing is nowadays ubiquitous, when unsure, it is
   646   * recommended to call this function with the %IDN2_NONTRANSITIONAL
   647   * and the %IDN2_NFC_INPUT flags for compatibility with other software.
   648   *
   649   * Return value: Returns %IDN2_OK on success, or error code.
   650   *
   651   * Since: 2.1.1
   652   **/
   653  int
   654  idn2_to_ascii_4i2 (const uint32_t * input, size_t inlen, char ** output, int flags)
   655  {
   656    uint32_t *input_u32;
   657    uint8_t *input_u8, *output_u8;
   658    size_t length;
   659    int rc;
   660
   661    if (!input)
   662      {
   663        if (output)
   664          *output = NULL;
   665        return IDN2_OK;
   666      }
   667
   668    input_u32 = (uint32_t *) malloc ((inlen + 1) * sizeof(uint32_t));
   669    if (!input_u32)
   670      return IDN2_MALLOC;
   671
   672    u32_cpy (input_u32, input, inlen);
   673    input_u32[inlen] = 0;
   674
   675    input_u8 = u32_to_u8 (input_u32, inlen + 1, NULL, &length);
   676    free (input_u32);
   677    if (!input_u8)
   678      {
   679        if (errno == ENOMEM)
   680          return IDN2_MALLOC;
   681        return IDN2_ENCODING_ERROR;
   682      }
   683
   684    rc = idn2_lookup_u8 (input_u8, &output_u8, flags);
   685    free (input_u8);
   686
   687    if (rc == IDN2_OK)
   688      {
   689        if (output)
   690          *output = (char *) output_u8;
   691                  else
   692          free (output_u8);
   693      }
   694
   695    return rc;
   696  }
