    44  /**
    45   * idn2_register_u8:
    46   * @ulabel: input zero-terminated UTF-8 and Unicode NFC string, or NULL.
    47   * @alabel: input zero-terminated ACE encoded string (xn--), or NULL.
    48   * @insertname: newly allocated output variable with name to register in DNS.
    49   * @flags: optional #idn2_flags to modify behaviour.
    50   *
    51   * Perform IDNA2008 register string conversion on domain label @ulabel
    52   * and @alabel, as described in section 4 of RFC 5891.  Note that the
    53   * input @ulabel must be encoded in UTF-8 and be in Unicode NFC form.
    54   *
    55   * Pass %IDN2_NFC_INPUT in @flags to convert input @ulabel to NFC form
    56   * before further processing.
    57   *
    58   * It is recommended to supply both @ulabel and @alabel for better
    59   * error checking, but supplying just one of them will work.  Passing
    60   * in only @alabel is better than only @ulabel.  See RFC 5891 section
    61   * 4 for more information.
    62   *
    63   * After version 0.11: @insertname may be NULL to test conversion of @src
    64   * without allocating memory.
    65   *
    66   * Returns: On successful conversion %IDN2_OK is returned, when the
    67   *   given @ulabel and @alabel does not match each other
    68   *   %IDN2_UALABEL_MISMATCH is returned, when either of the input
    69   *   labels are too long %IDN2_TOO_BIG_LABEL is returned, when @alabel
    70   *   does does not appear to be a proper A-label %IDN2_INVALID_ALABEL
    71   *   is returned, or another error code is returned.
    72   **/
    73  int
    74  idn2_register_u8 (const uint8_t * ulabel, const uint8_t * alabel,
    75                    uint8_t ** insertname, int flags)
    76  {
    77    int rc;
    78
    79    if (ulabel == NULL && alabel == NULL)
    80      {
    81        if (insertname)
    82          *insertname = NULL;
    83        return IDN2_OK;
    84      }
    85
    86    if (alabel)
    87      {
    88        size_t alabellen = strlen ((char *) alabel), u32len =
    89          IDN2_LABEL_MAX_LENGTH * 4;
    90        uint32_t u32[IDN2_DOMAIN_MAX_LENGTH * 4];
    91        uint8_t *tmp;
    92        uint8_t u8[IDN2_DOMAIN_MAX_LENGTH + 1];
    93        size_t u8len;
    94
    95        if (alabellen > IDN2_LABEL_MAX_LENGTH)
    96          return IDN2_TOO_BIG_LABEL;
    97
    98        if (alabellen <= 4)
    99          return IDN2_INVALID_ALABEL;
   100        if (alabel[0] != 'x'
   101            || alabel[1] != 'n' || alabel[2] != '-' || alabel[3] != '-')
   102          return IDN2_INVALID_ALABEL;
   103
   104        if (!_idn2_ascii_p (alabel, alabellen))
   105          return IDN2_INVALID_ALABEL;
   106
   107        rc = _idn2_punycode_decode (alabellen - 4, (char*)alabel + 4,
   108                                    &u32len, u32);
   109        if (rc != IDN2_OK)
   110          return rc;
   111
   112        u8len = sizeof (u8);
   113        if (u32_to_u8 (u32, u32len, u8, &u8len) == NULL)
   114          return IDN2_ENCODING_ERROR;
   115        u8[u8len] = '\0';
   116
   117        if (ulabel)
   118          {
   119            if (strcmp ((char*)ulabel, (char*)u8) != 0)
   120              return IDN2_UALABEL_MISMATCH;
   121          }
   122
   123        rc = idn2_register_u8 (u8, NULL, &tmp, 0);
   124        if (rc != IDN2_OK)
   125          return rc;
   126
   127        rc = strcmp ((char*)alabel, (char*)tmp);
   128        free (tmp);
   129        if (rc != 0)
   130          return IDN2_UALABEL_MISMATCH;
   131
   132        if (insertname)
   133          {
   134            uint8_t *m = (uint8_t *)strdup ((char*)alabel);
   135            if (!m)
   136              return IDN2_MALLOC;
   137
   138            *insertname = m;
   139          }
   140      }
   141    else                          /* ulabel only */
   142      {
   143        size_t ulabellen = u8_strlen (ulabel);
   144        uint32_t *u32;
   145        size_t u32len;
   146        size_t tmpl;
   147        uint8_t tmp[IDN2_LABEL_MAX_LENGTH + 1];
   148
   149        if (_idn2_ascii_p (ulabel, ulabellen))
   150          {
   151            if (ulabellen > IDN2_LABEL_MAX_LENGTH)
   152              return IDN2_TOO_BIG_LABEL;
   153
   154            if (insertname)
   155              {
   156                uint8_t *m = (uint8_t *)strdup ((char*)ulabel);
   157                if (!m)
   158                  return IDN2_MALLOC;
   159                *insertname = m;
   160              }
   161            return IDN2_OK;
   162          }
   163
   164        rc = _idn2_u8_to_u32_nfc (ulabel, ulabellen, &u32, &u32len,
   165                                  flags & IDN2_NFC_INPUT);
   166        if (rc != IDN2_OK)
   167          return rc;
   168
   169        rc = _idn2_label_test (TEST_NFC
   170                               | TEST_DISALLOWED
   171                               | TEST_UNASSIGNED
   172                               | TEST_2HYPHEN
   173                               | TEST_HYPHEN_STARTEND
   174                               | TEST_LEADING_COMBINING
   175                               | TEST_CONTEXTJ_RULE
   176                               | TEST_CONTEXTO_RULE | TEST_BIDI, u32, u32len);
   177        if (rc != IDN2_OK)
   178          {
   179            free (u32);
   180            return rc;
   181          }
   182
   183        tmp[0] = 'x';
   184        tmp[1] = 'n';
   185        tmp[2] = '-';
   186        tmp[3] = '-';
   187
   188        tmpl = IDN2_LABEL_MAX_LENGTH - 4;
   189        rc = _idn2_punycode_encode (u32len, u32, &tmpl, (char*)tmp + 4);
   190        free (u32);
   191        if (rc != IDN2_OK)
   192          return rc;
   193
   194        tmp[4 + tmpl] = '\0';
   195
   196        if (insertname)
   197          {
   198            uint8_t *m = (uint8_t *)strdup ((char*)tmp);
   199            if (!m)
   200              return IDN2_MALLOC;
   201            *insertname = m;
   202          }
   203      }
   204
   205    return IDN2_OK;
   206  }
